<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{ChartAccount,Company,FiscalPeriod,FiscalYear,JournalEntry}; use App\Services\{AccountingService,AuthorizationService}; use App\Support\TenantContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
final class AccountingController {
    public function accounts(Request $r){$q=ChartAccount::where('tenant_id',app(TenantContext::class)->id())->when($r->filled('company_id'),fn($q)=>$q->where(fn($x)=>$x->whereNull('company_id')->orWhere('company_id',$r->string('company_id'))))->orderBy('code');return response()->json(['data'=>$q->paginate(min($r->integer('per_page',50),100))]);}
    public function storeAccount(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'accounting.manage',$r->input('company_id')),403);$d=$r->validate(['company_id'=>'nullable|uuid','code'=>'required|alpha_dash|max:40','name'=>'required|string|max:200','type'=>'required|in:asset,liability,equity,revenue,expense','normal_balance'=>'required|in:debit,credit','is_control'=>'sometimes|boolean']);if(!empty($d['company_id']))abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);return response()->json(['data'=>ChartAccount::create([...$d,'tenant_id'=>$t])],201);}
    public function periods(Request $r){$t=app(TenantContext::class)->id();return response()->json(['data'=>FiscalPeriod::where('tenant_id',$t)->with('fiscalYear')->orderByDesc('starts_on')->paginate(50)]);}
    public function storePeriod(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','year_name'=>'required|string|max:100','period_name'=>'required|string|max:100','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on']);abort_unless($auth->allows($r->user(),$t,'accounting.manage',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);$year=FiscalYear::firstOrCreate(['tenant_id'=>$t,'company_id'=>$d['company_id'],'starts_on'=>$d['starts_on']],['name'=>$d['year_name'],'ends_on'=>$d['ends_on'],'state'=>'open']);$period=FiscalPeriod::create(['tenant_id'=>$t,'fiscal_year_id'=>$year->id,'name'=>$d['period_name'],'starts_on'=>$d['starts_on'],'ends_on'=>$d['ends_on'],'state'=>'open']);return response()->json(['data'=>$period],201);}
    public function closePeriod(Request $r,FiscalPeriod $period,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($period->tenant_id===$t,404);$year=$period->fiscalYear;abort_unless($auth->allows($r->user(),$t,'accounting.close',$year->company_id),403);$period->update(['state'=>'closed','closed_at'=>now(),'closed_by'=>$r->user()->id]);return response()->json(['data'=>$period->fresh()]);}
    public function post(Request $r,AccountingService $accounting,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','fiscal_period_id'=>'required|uuid','currency_id'=>'required|uuid','entry_date'=>'required|date','idempotency_key'=>'required|string|max:100','exchange_rate'=>'nullable|numeric|gt:0','description'=>'nullable|string','source_type'=>'nullable|string|max:100','source_id'=>'nullable|uuid','lines'=>'required|array|min:2','lines.*.account_id'=>'required|uuid','lines.*.debit'=>'nullable|numeric|min:0','lines.*.credit'=>'nullable|numeric|min:0','lines.*.description'=>'nullable|string']);abort_unless($auth->allows($r->user(),$t,'accounting.post',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);$entry=$accounting->post([...$d,'tenant_id'=>$t,'created_by'=>$r->user()->id]);return response()->json(['data'=>$entry],201);}
    public function reverse(Request $r,JournalEntry $entry,AccountingService $accounting,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($entry->tenant_id===$t,404);abort_unless($auth->allows($r->user(),$t,'accounting.post',$entry->company_id),403);return response()->json(['data'=>$accounting->reverse($entry,$r->validate(['idempotency_key'=>'required|string|max:100'])['idempotency_key'],$r->user()->id)],201);}
    public function trialBalance(Request $r,AccountingService $accounting){$d=$r->validate(['company_id'=>'required|uuid','from'=>'required|date','to'=>'required|date|after_or_equal:from']);return response()->json(['data'=>$accounting->trialBalance(app(TenantContext::class)->id(),$d['company_id'],$d['from'],$d['to'])]);}
    public function financialReport(Request $r,AccountingService $accounting){$d=$r->validate(['company_id'=>'required|uuid','from'=>'required|date','to'=>'required|date|after_or_equal:from','type'=>'required|in:profit_loss,balance_sheet,cash_flow']);$rows=$accounting->trialBalance(app(TenantContext::class)->id(),$d['company_id'],$d['from'],$d['to']);$types=$d['type']==='profit_loss'?['revenue','expense']:($d['type']==='balance_sheet'?['asset','liability','equity']:['asset']);return response()->json(['data'=>array_values(array_filter($rows,fn($row)=>in_array($row['account_type']??null,$types,true))),'report_type'=>$d['type']]);}
}
